    for(const auto& canvas:document.canvases)if(!canvas.asset.empty())need(findImageAsset(document,canvas.asset),"Canvas references a missing embedded image: "+canvas.asset);
    for(const auto& feature:document.features){appearanceAsset(document,resolvedAppearance(document,feature));need(feature.faceAppearances.size()<=128,"Face appearance capacity exceeded");std::set<std::string> faces;std::set<int> faceIndices;const auto body=resolvedAppearance(document,feature);for(const auto& patch:feature.faceAppearances){checkFace(patch);need(faces.insert(patch.face).second,"Duplicate face appearance");Appearance face=body;if(!patch.material.empty()){const auto* chosen=material(document,patch.material);need(chosen,"Face appearance references a missing material: "+patch.material);face=chosen->appearance;}if(patch.appearance.t==V::Obj){std::string error;need(applyAppearancePatch(face,patch.appearance,error),error);}need(std::abs(face.opacity-body.opacity)<1e-9,"Face opacity must equal body opacity; independent transparent face sorting is unsupported");appearanceAsset(document,face);if(validateGeometry&&active.count(feature.id))need(faceIndices.insert(appearanceFaceIndex024B(document,feature.id,patch.face,patch.sourceTopology)).second,"Two appearance recipes resolve to the same exact face through different aliases");}}
